import { Catalogue } from '../domain/Catalogue';
import { Product } from '../domain/Product';

export class CatalogueService {
  constructor(private catalogue: Catalogue) {}

  addProduct(id: string, name: string, price: number, stock: number): void {
    const product: Product = { id, name, price };
    this.catalogue.addProduct(id, product, stock);
  }

  getProductWithStock(productId: string): { product: Product; available: number; reserved: number } | null {
    const product = this.catalogue.getProduct(productId);
    if (!product) return null;

    return {
      product,
      available: this.catalogue.getAvailableStock(productId),
      reserved: this.catalogue.getReservedStock(productId),
    };
  }

  getAllProductsWithStock(): Array<{ product: Product; available: number; reserved: number; total: number }> {
    return this.catalogue.getAllProducts().map(product => ({
      product,
      available: this.catalogue.getAvailableStock(product.id),
      reserved: this.catalogue.getReservedStock(product.id),
      total: this.catalogue.getTotalStock(product.id),
    }));
  }
}

